<script setup lang="ts">
import {ref,computed,watch,onMounted,onBeforeUnmount,nextTick} from 'vue';
import Waveform from './Waveform.vue';
import SubtitlePanel from './SubtitlePanel.vue';
import VideoLibrary from './VideoLibrary.vue';
import {deviceLabel} from './deviceLabel';
import {cyclePlan,cycleLevel,cycleMS,peakTimes,frequencyAt,type Action} from './timeline';
type DiscoveredDevice={name:string;address:string;identity:string;signal:number};
type NativeState={fullscreen:boolean;time:number;duration:number;paused:boolean;seeking:boolean;buffering:boolean;loaded:boolean;ended?:boolean;message:string;connected?:boolean;name?:string;source?:string;rate?:number;sync_enabled?:boolean};
type VideoSelection={kind:string;name:string;url:string;script:{name:string;points:Action[]}|null;warning:string};
type API={FinishPlaybackOutput:()=>Promise<void>;TestHandyPosition:(position:number)=>Promise<void>;SavedHandyKey:()=>Promise<string>;SetDeviceMode:(mode:string)=>Promise<void>;ConnectHandy:(key:string)=>Promise<void>;SetDeoConnectionMode:(mode:string)=>Promise<void>;CopyDeoMediaAddress:()=>Promise<void>;DeoMediaAddress:()=>Promise<string>;PlaybackPointerState:()=>Promise<{x:number;y:number;inside:boolean}>;FollowDeoMedia:(source:string)=>Promise<VideoSelection>;SetLibraryExpanded:(expanded:boolean)=>Promise<void>;OpenLibraryVideo:(id:string)=>Promise<VideoSelection>;SetPlaybackMode:(mode:string)=>Promise<void>;ConnectDeo:(host:string)=>Promise<void>;DisconnectDeo:()=>Promise<void>;TickDeo:(offset:number,stroke:boolean,vibration:boolean)=>Promise<void>;PlaybackLayout:(x:number,y:number,w:number,h:number,viewport:number,overlay:number)=>Promise<void>;PlaybackState:()=>Promise<NativeState>;PlaybackPause:(pause:boolean)=>Promise<void>;PlaybackSeek:(seconds:number)=>Promise<void>;PlaybackVolume:(volume:number)=>Promise<void>;PlaybackFullscreen:(full:boolean)=>Promise<void>;DiscoverDevices:()=>Promise<DiscoveredDevice[]>;ConnectDevice:(name:string,identity:string)=>Promise<void>;ReportPlayback:(event:string,snapshot:Record<string,unknown>)=>Promise<void>;Connect:(a:string)=>Promise<void>;Disconnect:()=>Promise<void>;DeviceState:()=>Promise<{connected:boolean;message:string;kind:string}>;Stop:()=>Promise<void>;Tick:(t:number,s:boolean,v:boolean)=>Promise<void>;OpenVideo:()=>Promise<VideoSelection|null>;OpenScript:()=>Promise<{name:string;actions:number;duration:number;points:Action[]}|null>};
const api=()=> (window as unknown as {go:{main:{App:API}}}).go.main.App;
const devices=ref<DiscoveredDevice[]>([]),selectedIdentity=ref(''),connected=ref(false),busy=ref(false),status=ref('请先连接设备'),strokeEnabled=ref(true),vibrationEnabled=ref(false),offset=ref(0),videoName=ref(''),scriptName=ref(''),stage=ref<HTMLElement>(),source=ref(''),armed=ref(false);try{const saved=JSON.parse(localStorage.getItem('selectedDevice')||'null');if(typeof saved?.name==='string'&&typeof saved.identity==='string'){devices.value=[{name:saved.name,identity:saved.identity,address:'',signal:0}];selectedIdentity.value=saved.identity}}catch{}
const endpointTesting=ref(false);
const deviceMode=ref('bluetooth'),handyKey=ref(''),deviceKind=ref('bluetooth');
const isHandy=computed(()=>deviceMode.value==='internet'||deviceKind.value==='handy-bluetooth');
async function changeDeviceMode(){busy.value=true;try{await pauseVideo();await api().SetDeviceMode(deviceMode.value);connected.value=false;deviceKind.value='bluetooth';vibrationEnabled.value=false;status.value='请选择并连接设备'}catch(e){const state=await api().DeviceState().catch(()=>null);if(state)deviceMode.value=state.kind==='handy-internet'?'internet':'bluetooth';status.value=String(e)}finally{busy.value=false}}
async function connectInternet(){busy.value=true;try{await api().ConnectHandy(handyKey.value);connected.value=true;deviceKind.value='handy-internet';vibrationEnabled.value=false;status.value='Handy 已连接';await readPlayback();if(playing.value)play()}catch(e){connected.value=false;status.value=String(e)}finally{busy.value=false}}
async function testEndpoint(position:number){busy.value=true;endpointTesting.value=true;try{await pauseVideo();for(let i=0;i<50;i++){const state=await api().PlaybackState();if(!state.loaded||state.paused)break;if(i===49)throw Error("播放尚未暂停");await new Promise(resolve=>window.setTimeout(resolve,20))}await api().TestHandyPosition(position);status.value=`已发送测试位置 ${position}`}catch(e){status.value=String(e)}finally{endpointTesting.value=false;busy.value=false}}
const deoMediaAddress=ref('');
const audioCaption=ref({original:'',translation:''});const mediaKind=ref('video');const mediaBusy=ref(false),librarySelected=ref('');const modeBusy=ref(false);const playbackMode=ref('mpv'),deoConnectionMode=ref('remote'),deoConnected=ref(false),deoSync=ref(false),deoBusy=ref(false),deoMessage=ref('');
async function changePlaybackMode(){modeBusy.value=true;try{await pauseVideo();await stop();deoSync.value=false;deoConnected.value=false;source.value='';videoName.value='';scriptName.value='';points.value=[];mediaKind.value='video';currentMs.value=0;durationMs.value=0;await api().SetPlaybackMode(playbackMode.value);deoMediaAddress.value=await api().DeoMediaAddress();await layout()}catch(e){status.value=String(e)}finally{modeBusy.value=false}}
async function changeDeoConnectionMode(){deoBusy.value=true;try{await api().SetDeoConnectionMode(deoConnectionMode.value);deoConnected.value=false;deoSync.value=false;deoMediaAddress.value=await api().DeoMediaAddress();await stop()}catch(e){status.value=String(e)}finally{deoBusy.value=false}}

const selectedDevice=computed(()=>devices.value.find(d=>d.identity===selectedIdentity.value));
let timer:number;let sending=false;
const points=ref<Action[]>([]),currentMs=ref(0),durationMs=ref(0),playing=ref(false);
let stateTimer:number,stateReading=false;
let logTimer:number;let nativeReading=false;let observer:ResizeObserver;const volume=ref(100),fullscreen=ref(false);const native=ref<NativeState>({fullscreen:false,time:0,duration:0,paused:true,seeking:false,buffering:false,loaded:false,message:''});
const controlsVisible=ref(true),playbackControls=ref<HTMLElement>();let hideControlsTimer:number|undefined;let pointerSample='',domPointerSample='';
const scriptPeaks=computed(()=>peakTimes(points.value));
const scriptFrequency=computed(()=>frequencyAt(scriptPeaks.value,Math.max(0,currentMs.value+offset.value)));
function revealControls(){controlsVisible.value=true;window.clearTimeout(hideControlsTimer);if(fullscreen.value)hideControlsTimer=window.setTimeout(()=>{if(!dragging.value&&!seekBusy.value)controlsVisible.value=false;else revealControls()},3000)}
function pointerMoved(event:PointerEvent){const sample=`${event.screenX}:${event.screenY}`;if(sample!==domPointerSample){domPointerSample=sample;revealControls()}}
async function readPointer(){if(!fullscreen.value)return;try{const p=await api().PlaybackPointerState();const sample=`${p.x}:${p.y}`;if(p.inside&&sample!==pointerSample)revealControls();pointerSample=sample}catch{}}
watch(fullscreen,()=>{pointerSample='';domPointerSample='';revealControls()});
function logPlayback(event:string,message=''){api().ReportPlayback(event,{time_ms:currentMs.value,duration_ms:durationMs.value,paused:native.value.paused,seeking:native.value.seeking,armed:armed.value,connected:connected.value,has_script:!!scriptName.value,stroke_enabled:strokeEnabled.value,vibration_enabled:vibrationEnabled.value,output:output.value,offset:offset.value,message}).catch(()=>{})}
function jsLog(event:ErrorEvent){logPlayback('js_error',event.message)}
function promiseLog(event:PromiseRejectionEvent){logPlayback('js_error',String(event.reason))}
async function pauseVideo(){armed.value=false;playing.value=false;await stop();if(source.value)await api().PlaybackPause(true).catch(()=>{});armed.value=false;playing.value=false;await stop()}
async function layout(){if(playbackMode.value==='deovr')return;const r=stage.value?.getBoundingClientRect();if(r)await api().PlaybackLayout(r.x,r.y,r.width,r.height,window.innerWidth,fullscreen.value&&controlsVisible.value?(playbackControls.value?.getBoundingClientRect().height||0):0).catch(()=>{})}
async function readPlayback(){if(nativeReading||modeBusy.value||mediaBusy.value||endpointTesting.value)return;nativeReading=true;try{const s=await api().PlaybackState();native.value=s;if(fullscreen.value!==s.fullscreen){fullscreen.value=!!s.fullscreen;await nextTick();await layout()}if(playbackMode.value==='deovr'){deoConnected.value=!!s.connected;deoSync.value=!!s.sync_enabled;if(!s.sync_enabled)armed.value=false;deoMessage.value=s.message||'';const nextSource=s.source||'';if(nextSource!==source.value){armed.value=false;await stop();scriptName.value='';points.value=[];source.value=nextSource;if(nextSource){const media=await api().FollowDeoMedia(nextSource);scriptName.value=media.script?.name||'';points.value=media.script?.points||[];status.value=media.warning||(media.script?'已自动匹配脚本':'未找到同名脚本');}}videoName.value=s.name||'';}await readPointer();if(!dragging.value&&!seekBusy.value)currentMs.value=Math.round(s.time*1000)||0;durationMs.value=Math.round(s.duration*1000)||0;const active=!dragging.value&&!seekBusy.value&&s.loaded&&!s.paused&&!s.seeking&&!s.buffering&&!s.ended;if(playing.value&&!active){armed.value=false;if(s.ended&&!dragging.value&&!seekBusy.value&&!s.seeking)await api().FinishPlaybackOutput();else await stop();}if(active&&(!playing.value||(playbackMode.value==='deovr'&&deoSync.value&&!armed.value)))play();playing.value=active;if(s.message)status.value=s.message;}catch(e){await stop();playing.value=false;status.value=String(e)}finally{nativeReading=false}}
const dragging=ref(false),seekBusy=ref(false);let resumeAfterSeek=false,dragPause:Promise<void>=Promise.resolve(),dragGeneration=0;
watch([controlsVisible,dragging,seekBusy],async()=>{await nextTick();await layout()});
function beginScrub(){if(!source.value||dragging.value||seekBusy.value)return;dragging.value=true;dragGeneration++;resumeAfterSeek=!native.value.paused;armed.value=false;playing.value=false;dragPause=(async()=>{await stop();await api().PlaybackPause(true)})().catch(e=>{status.value=String(e);resumeAfterSeek=false});logPlayback('seeking','drag.begin')}
function previewScrub(seconds:number){if(!dragging.value)beginScrub();if(!dragging.value)return;currentMs.value=Math.max(0,Math.min(durationMs.value,Math.round(seconds*1000)))}
async function finishScrub(seconds:number){if(!dragging.value||seekBusy.value)return;const generation=dragGeneration;dragging.value=false;seekBusy.value=true;const target=Math.max(0,Math.min(durationMs.value/1000,seconds));currentMs.value=Math.round(target*1000);try{await dragPause;await api().PlaybackSeek(target);if(generation!==dragGeneration)return;if(resumeAfterSeek)await api().PlaybackPause(false);logPlayback('seeked','drag.commit')}catch(e){status.value=String(e)}finally{seekBusy.value=false}}
async function cancelScrub(){if(!dragging.value)return;dragging.value=false;seekBusy.value=true;try{await dragPause;if(resumeAfterSeek)await api().PlaybackPause(false)}catch(e){status.value=String(e)}finally{seekBusy.value=false}}
function formatTime(ms:number){const s=Math.floor(ms/1000);return Math.floor(s/60)+':'+String(s%60).padStart(2,'0')}
async function toggleFullscreen(){const full=!fullscreen.value;try{await api().PlaybackFullscreen(full);fullscreen.value=full;await nextTick();await layout();setTimeout(layout,150)}catch(e){status.value=String(e)}}
function fullscreenKeys(e:KeyboardEvent){if(fullscreen.value)revealControls();if(e.key==='Escape'&&fullscreen.value){e.preventDefault();toggleFullscreen()}else if(e.key.toLowerCase()==='f'&&!(e.target instanceof HTMLInputElement)&&!(e.target instanceof HTMLSelectElement)){e.preventDefault();toggleFullscreen()}}
watch([strokeEnabled,vibrationEnabled,offset],()=>logPlayback('parameters'));
async function readDeviceState(){if(busy.value||stateReading)return;stateReading=true;try{const s=await api().DeviceState();if(busy.value)return;deviceKind.value=s.kind||'bluetooth';if(connected.value&&!s.connected){connected.value=false;armed.value=false;pauseVideo();status.value=s.message}}catch(e){status.value=String(e)}finally{stateReading=false}}
const plannedCycles=computed(()=>cyclePlan(points.value));
const output=computed(()=>!connected.value?0:armed.value&&playing.value&&strokeEnabled.value?plannedOutput():0);
function plannedOutput(){const ms=Math.max(0,currentMs.value+offset.value);const cycles=plannedCycles.value;let lo=0,hi=cycles.length;while(lo<hi){const mid=(lo+hi)>>>1;if(cycles[mid].start<=ms)lo=mid+1;else hi=mid;}const c=cycles[lo-1];if(!c||ms>=c.end)return 0;const rate=playbackMode.value==='deovr'?Math.max(0.001,native.value.rate||1):1;const period=(c.end-c.start)/rate;const level=cycleLevel(period,10);if(period<cycleMS[10])return 10;return level>0&&(ms-c.start)/rate<cycleMS[level]?level:0;}
async function seekFromWave(seconds:number){if(!source.value||seekBusy.value)return;beginScrub();previewScrub(seconds);await finishScrub(seconds)}
async function stop(){armed.value=false;try{await api().Stop()}catch(e){status.value=String(e)}}
async function scanDevices(){if(busy.value||connected.value)return;busy.value=true;status.value='正在扫描设备…';try{const found=await api().DiscoverDevices();devices.value=found;if(!found.some(d=>d.identity===selectedIdentity.value))selectedIdentity.value=found[0]?.identity||'';status.value=found.length?'请选择设备连接':'未找到支持的设备'}catch(e){status.value=String(e)}finally{busy.value=false}}
async function connect(){const d=selectedDevice.value;if(!d){await scanDevices();return}busy.value=true;status.value='正在查找并连接设备…';try{await api().ConnectDevice(d.name,d.identity);deviceKind.value=(await api().DeviceState()).kind||'bluetooth';if(isHandy.value)vibrationEnabled.value=false;connected.value=true;try{localStorage.setItem('selectedDevice',JSON.stringify({name:d.name,identity:d.identity}))}catch{}status.value='设备已连接';await readPlayback();if(playing.value){play();logPlayback('sync.attached');}}catch(e){connected.value=false;status.value=String(e)}finally{busy.value=false}}
async function disconnect(){busy.value=true;connected.value=false;armed.value=false;pauseVideo();try{await api().Disconnect();status.value='设备已断开'}catch(e){status.value='设备已断开：'+String(e)}finally{busy.value=false}}
function acceptVideo(n:VideoSelection){mediaKind.value=n.kind||'video';videoName.value=n.name;source.value=n.url+Date.now();scriptName.value=n.script?.name||'';points.value=n.script?.points||[];currentMs.value=0;durationMs.value=0;status.value=n.warning||(n.script?'已加载媒体和同名脚本':'已加载媒体');}
async function openVideo(){if(mediaBusy.value)return;mediaBusy.value=true;try{dragGeneration++;resumeAfterSeek=false;await cancelScrub();await pauseVideo();await layout();const n=await api().OpenVideo();if(n){acceptVideo(n);librarySelected.value=''}}catch(e){scriptName.value='';points.value=[];status.value=String(e)}finally{mediaBusy.value=false}}
async function openLibraryVideo(id:string){if(mediaBusy.value||modeBusy.value)return;if(playbackMode.value==='deovr'&&!deoConnected.value){status.value='请先连接 DeoVR';return}mediaBusy.value=true;try{dragGeneration++;resumeAfterSeek=false;await cancelScrub();await pauseVideo();await layout();scriptName.value='';points.value=[];const n=await api().OpenLibraryVideo(id);acceptVideo(n);librarySelected.value=id}catch(e){status.value=String(e)}finally{mediaBusy.value=false}}
async function openScript(){if(mediaBusy.value)return;await pauseVideo();await stop();try{const s=await api().OpenScript();if(s){scriptName.value=s.name;points.value=s.points;if(!cyclePlan(s.points).length)status.value='脚本没有完整往返，播放不会输出动作'}}catch(e){status.value=String(e)}}
async function tick(){if(sending||!connected.value||modeBusy.value||mediaBusy.value)return;sending=true;try{if(armed.value&&playing.value){if(playbackMode.value==='deovr')await api().TickDeo(offset.value,strokeEnabled.value,vibrationEnabled.value);else await api().Tick(Math.max(0,currentMs.value+offset.value),strokeEnabled.value,vibrationEnabled.value)}}catch(e){pauseVideo();armed.value=false;status.value=String(e);await api().Stop().catch(()=>{})}finally{sending=false}}
function play(){armed.value=connected.value&&!!scriptName.value&&(playbackMode.value!=='deovr'||deoSync.value);if(!armed.value)status.value='同步未就绪'}
onMounted(()=>{api().SavedHandyKey().then(key=>{if(!handyKey.value)handyKey.value=key}).catch(e=>{status.value=String(e)});timer=window.setInterval(async()=>{if(nativeReading||modeBusy.value||mediaBusy.value||endpointTesting.value)return;await readPlayback();await tick()},100);stateTimer=window.setInterval(readDeviceState,500);logTimer=window.setInterval(()=>logPlayback('snapshot'),10000);window.addEventListener('error',jsLog);window.addEventListener('unhandledrejection',promiseLog);window.addEventListener('resize',layout);window.addEventListener('keydown',fullscreenKeys);observer=new ResizeObserver(layout);if(stage.value)observer.observe(stage.value);layout()});onBeforeUnmount(()=>{window.clearInterval(timer);window.clearInterval(stateTimer);window.clearInterval(logTimer);window.clearTimeout(hideControlsTimer);observer?.disconnect();window.removeEventListener('resize',layout);window.removeEventListener('keydown',fullscreenKeys);window.removeEventListener('error',jsLog);window.removeEventListener('unhandledrejection',promiseLog);stop()});
async function channelsChanged(){logPlayback("parameters");if(!connected.value)return;if(playing.value)play();if(armed.value&&playing.value){await tick()}else{await stop()}}
async function togglePlayback(){if(!source.value)return;try{const paused=!native.value.paused;await api().PlaybackPause(paused);native.value.paused=paused;if(!paused)play();else {playing.value=false;await stop()}}catch(e){status.value=String(e)}}
</script>
<template>
<main class="app-shell" :class="{'playback-fullscreen':fullscreen,'controls-hidden':fullscreen&&!controlsVisible&&!dragging&&!seekBusy}" @pointermove="pointerMoved">

  
  <div class="workspace">
    <aside class="library-panel">
      <VideoLibrary :audio-allowed="playbackMode==='mpv'" :busy="mediaBusy||modeBusy||seekBusy||dragging" :selected="librarySelected" @select="openLibraryVideo" @expand="api().SetLibraryExpanded($event)"/>
      <section class="side-section"><div class="section-heading"><h2>媒体</h2><span class="count">{{(source?1:0)+(scriptName?1:0)}} / 2</span></div><button class="file-card" :disabled="mediaBusy||(playbackMode==='deovr'&&!deoConnected)" @click="openVideo"><span class="file-icon">▷</span><span class="file-content"><span class="file-label">{{mediaKind==='audio'?'音声':'视频 / 音声'}}</span><span class="file-name" :title="videoName">{{videoName||(playbackMode==='deovr'?'选择视频':'选择视频或音声')}}</span></span><span class="file-arrow">＋</span></button><button class="file-card" :disabled="mediaBusy" @click="openScript"><span class="file-icon script-icon">∿</span><span class="file-content"><span class="file-label">脚本</span><span class="file-name" :title="scriptName">{{scriptName||'选择脚本'}}</span></span><span class="file-arrow">＋</span></button><button class="primary play-button" :disabled="!source" @click="togglePlayback">{{playing?'暂停播放':'播放'}}</button></section>
    </aside>
    <div class="view-panel">
      <div class="player-surface"><section class="video-stage" ref="stage"><div v-if="playbackMode==='deovr'" class="empty-state"><div class="play-symbol">VR</div><h2>DeoVR</h2><span>{{deoConnected?(native.loaded?'画面在头显中播放':'等待 DeoVR 打开视频'):'等待连接'}}</span></div><div v-else-if="mediaKind==='audio'" class="empty-state audio-stage"><div class="play-symbol">♪</div><h2 :title="videoName">{{videoName}}</h2><div v-if="audioCaption.translation||audioCaption.original" class="audio-caption" aria-live="off"><div v-if="audioCaption.original" class="caption-original">{{audioCaption.original}}</div><div v-if="audioCaption.translation" class="caption-translation">{{audioCaption.translation}}</div></div></div><div v-else-if="!source" class="empty-state idle-stage"><button class="idle-open" :disabled="mediaBusy" @click="openVideo" aria-label="选择媒体"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><path d="M3 7a2 2 0 0 1 2-2h5l2 2h7a2 2 0 0 1 2 2v10H3Z"/><path d="m10 11 5 3-5 3Z"/></svg></button></div></section>
      <div class="playback-controls" ref="playbackControls" @focusin="revealControls"><button :disabled="!source" @click="togglePlayback">{{playing?'Ⅱ':'▷'}}</button><span>{{formatTime(currentMs)}} / {{formatTime(durationMs)}}</span><input type="range" min="0" :max="durationMs||1" :value="currentMs" :disabled="!source||seekBusy" @pointerdown="beginScrub" @input="previewScrub(Number(($event.target as HTMLInputElement).value)/1000)" @change="finishScrub(Number(($event.target as HTMLInputElement).value)/1000)" @pointerup="finishScrub(Number(($event.target as HTMLInputElement).value)/1000)" @pointercancel="cancelScrub" aria-label="播放进度"><span class="progress-frequency" :title="scriptName?'脚本频率':'未加载脚本'">{{scriptFrequency.toFixed(2)}} <small>Hz</small></span><input v-if="playbackMode==='mpv'" class="volume" type="range" min="0" max="100" v-model.number="volume" :disabled="!source" @input="api().PlaybackVolume(volume)"><button @click="toggleFullscreen">{{fullscreen?'退出全屏':'全屏'}}</button></div>
      </div>
      <Waveform :points="points" :time="currentMs" :duration="durationMs" :offset="offset" :output="output" :can-seek="!!source&&durationMs>0&&!seekBusy" @seek="seekFromWave" @seek-start="beginScrub" @seek-preview="previewScrub" @seek-end="finishScrub" @seek-cancel="cancelScrub"/>
    </div>
    <aside class="sidebar">
      <section class="side-section"><div class="section-heading"><h2>播放模式</h2></div><div class="playback-mode-options" role="radiogroup" aria-label="播放模式"><label :class="{selected:playbackMode==='mpv'}"><input type="radio" name="playback-mode" value="mpv" v-model="playbackMode" :disabled="mediaBusy||modeBusy||deoBusy||seekBusy||dragging" @change="changePlaybackMode"><span>本地播放</span></label><label :class="{selected:playbackMode==='deovr'}"><input type="radio" name="playback-mode" value="deovr" v-model="playbackMode" :disabled="mediaBusy||modeBusy||deoBusy||seekBusy||dragging" @change="changePlaybackMode"><span>DeoVR</span></label></div><template v-if="playbackMode==='deovr'"><label v-if="deoMediaAddress" class="field">媒体库地址<input readonly :value="deoMediaAddress" @focus="($event.target as HTMLInputElement).select()"></label><button v-if="deoMediaAddress" @click="api().CopyDeoMediaAddress()">复制媒体库地址</button><div class="playback-mode-options" role="radiogroup" aria-label="DeoVR 连接位置"><label :class="{selected:deoConnectionMode==='local'}"><input type="radio" name="deo-location" value="local" v-model="deoConnectionMode" :disabled="deoBusy||modeBusy" @change="changeDeoConnectionMode"><span>本地</span></label><label :class="{selected:deoConnectionMode==='remote'}"><input type="radio" name="deo-location" value="remote" v-model="deoConnectionMode" :disabled="deoBusy||modeBusy" @change="changeDeoConnectionMode"><span>远程</span></label></div><div v-if="deoMessage" class="subtitle-status">{{deoMessage}}</div></template></section>


      <section class="side-section"><div class="section-heading"><h2>设备</h2><span class="device-dot" :class="{online:connected}"></span></div><div class="playback-mode-options"><label :class="{selected:deviceMode==='bluetooth'}"><input type="radio" value="bluetooth" v-model="deviceMode" :disabled="busy" @change="changeDeviceMode">蓝牙</label><label :class="{selected:deviceMode==='internet'}"><input type="radio" value="internet" v-model="deviceMode" :disabled="busy" @change="changeDeviceMode">互联网</label></div><template v-if="deviceMode==='internet'"><label class="field">Handy key<input type="password" autocomplete="off" v-model="handyKey" :disabled="connected||busy"></label><button :disabled="busy||(!connected&&!handyKey.trim())" @click="connected?disconnect():connectInternet()">{{busy?'处理中…':connected?'断开连接':'连接 Handy'}}</button></template><template v-else><div class="device-name">{{selectedDevice?deviceLabel(selectedDevice):'选择蓝牙设备'}}</div><label class="field">设备<select v-model="selectedIdentity" :disabled="connected||busy"><option value="" disabled>选择设备</option><option v-for="d in devices" :key="d.identity" :value="d.identity">{{deviceLabel(d)}}</option></select></label><div class="device-actions"><button class="connect-button" :disabled="connected||busy" @click="scanDevices">扫描设备</button><button class="connect-button" :disabled="busy||(!connected&&!selectedDevice)" @click="connected?disconnect():connect()">{{busy?'处理中…':connected?'断开连接':'连接设备'}}</button></div></template><div v-if="deviceKind==='handy-bluetooth'" class="device-actions endpoint-tests"><button :disabled="!connected||busy" @click="testEndpoint(0)">0</button><button :disabled="!connected||busy" @click="testEndpoint(100)">100</button></div></section>
      <section class="side-section"><div class="section-heading"><h2>同步</h2><span class="auto-tag">自动</span></div><div class="channel-switches motion-channels"><label>伸缩<input type="checkbox" v-model="strokeEnabled" @change="channelsChanged" role="switch"></label><label>震动<input type="checkbox" v-model="vibrationEnabled" :disabled="isHandy" @change="channelsChanged" role="switch"></label></div><label class="field">时间偏移（ms）<input type="number" v-model.number="offset" step="100"></label></section>
      <SubtitlePanel :audio-only="mediaKind==='audio'" @caption="audioCaption=$event" @picker="api().SetLibraryExpanded($event)" v-if="playbackMode==='mpv'" :time="currentMs" :source="source"/>
      <div class="session-status" role="status"><span class="status-dot"></span><span>{{status}}</span></div>
    </aside>
  </div>
</main>
</template>
<style>


