y-state{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:16px;background:radial-gradient(ellipse at center,#171e31 0,#080b12 72%)}.play-symbol{width:68px;height:68px;border:1px solid #37415b;background:#1c2436;border-radius:20px;display:grid;place-items:center;color:#9faafd;font-size:40px}.empty-state h2{font-size:20px;font-weight:500;margin:0;color:#b8c1d5}.primary{background:#7887ef;color:#101426;border-color:#8997ff;font-weight:650}.primary:hover{background:#919fff;border-color:#aab4ff}.sidebar{background:#131822;border:1px solid #262e3c;border-radius:14px;padding:20px;display:flex;flex-direction:column;gap:24px;min-width:0;overflow-y:auto}.side-section{display:flex;flex-direction:column;gap:12px}.section-heading{display:flex;align-items:center;justify-content:space-between}.section-heading h2{font-size:14px;margin:0;font-weight:600;color:#dce2f0}.count{font-size:12px;color:#6e7a91;font-variant-numeric:tabular-nums}.file-card{display:flex;align-items:center;text-align:left;gap:10px;padding:12px 10px;background:#1a202d;border-color:#2b3445;width:100%}.file-icon{flex-shrink:0;font-size:23px;color:#9ca9ff;background:#262e49;border-radius:8px;width:34px;height:38px;display:grid;place-items:center}.script-icon{color:#7fdbcb;background:#1a3736}.file-content{min-width:0;display:flex;flex-direction:column;gap:5px;flex:1}.file-label{font-size:12px;color:#8c99af}.file-name{font-size:13px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;display:block}.file-arrow{font-size:20px;color:#6d7a92}.play-button,.connect-button{width:100%;font-size:13px}.device-name{font-size:15px;color:#c2cce0}.field{display:flex;flex-direction:column;gap:8px;font-size:12px;color:#8896ad}.field input{width:100%;font-size:13px}.auto-tag{background:#233732;color:#7bd4b7;padding:3px 8px;border-radius:5px;font-size:11px}.session-status{margin-top:auto;border-top:1px solid #283142;padding-top:16px;display:flex;gap:9px;align-items:flex-st